import React from 'react';

const styles = {
  container: {
    padding: '40px 24px', // Added more vertical padding
    maxWidth: '1000px',
    margin: '0 auto',
    minHeight: '60vh', // Ensures the page has some height
  },
  heading: {
    fontSize: '2.5rem',
    marginBottom: '24px',
    textAlign: 'center',
  },
  paragraph: {
    fontSize: '1.1rem',
    lineHeight: '1.7',
    marginBottom: '16px',
  }
};

const TermsAndConditions = () => {
  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>Terms and Conditions</h1>
      <p style={styles.paragraph}>
        Welcome to Karpagam Clinic! These terms and conditions outline the rules and regulations for the use of Karpagam Clinic's Website, located at our domain.
      </p>
      <p style={styles.paragraph}>
        By accessing this website we assume you accept these terms and conditions. Do not continue to use Karpagam Clinic if you do not agree to take all of the terms and conditions stated on this page.
      </p>
      <p style={styles.paragraph}>
        The following terminology applies to these Terms and Conditions, Privacy Statement and Disclaimer Notice and all Agreements: "Client", "You" and "Your" refers to you, the person log on this website and compliant to the Company’s terms and conditions.
      </p>
      {/* Add more terms and conditions content as needed */}
    </div>
  );
};

export default TermsAndConditions;
